// src/dash/epaPriors.ts
// Season-start priors for the Bayesian EPA model: each team's standardized
// end-of-season strength for the previous three seasons, generated by
// scripts/build-epa-priors.ts into ./epaPriors/<year>.json. Each file is its
// own lazy chunk (~30 KB gzipped), precached by the service worker so the
// model works offline; a season with no file degrades to rookie-level priors.

import type { PriorZ } from '@/dash/bayesEpa';

const files = import.meta.glob<Record<string, Array<number | null>>>('./epaPriors/*.json', {
  import: 'default',
});

const cache = new Map<string, Promise<ReadonlyMap<number, PriorZ>>>();
const EMPTY: ReadonlyMap<number, PriorZ> = new Map();

export function loadEpaPriors(year: string): Promise<ReadonlyMap<number, PriorZ>> {
  let p = cache.get(year);
  if (!p) {
    const load = files[`./epaPriors/${year}.json`];
    p = load
      ? load()
          .then((obj) => {
            const out = new Map<number, PriorZ>();
            for (const [team, zs] of Object.entries(obj)) {
              out.set(Number(team), [zs[0] ?? null, zs[1] ?? null, zs[2] ?? null]);
            }
            return out as ReadonlyMap<number, PriorZ>;
          })
          .catch(() => {
            cache.delete(year);
            return EMPTY;
          })
      : Promise.resolve(EMPTY);
    cache.set(year, p);
  }
  return p;
}
